	/**
	 * Default Constructor
	 */
    public CabinLayoutService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new CabinLayoutEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(CabinLayoutRepository.class) );
		this.validator		= applicationContext.getBean(CabinLayoutValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		CabinLayout
	 */
		public CabinLayout createCabinLayout( CreateCabinLayoutCommand command ) {

		CabinLayout entity = new CabinLayout();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setCabinLayoutId( command.getCabinLayoutId() );
            entity.setLayoutCode( command.getLayoutCode() );
            entity.setTotalSeats( command.getTotalSeats() );
            entity.setClassLayout( command.getClassLayout() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of CabinLayout {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateCabinLayoutCommand
	 * @return		CabinLayout
	 */
	public CabinLayout updateCabinLayout( UpdateCabinLayoutCommand command ) {

		CabinLayout entity = new CabinLayout();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setCabinLayoutId( command.getCabinLayoutId() );
            entity.setLayoutCode( command.getLayoutCode() );
            entity.setTotalSeats( command.getTotalSeats() );
            entity.setClassLayout( command.getClassLayout() );
            entity.setVariant( command.getVariant() );
            entity.setAircraft( command.getAircraft() );
            entity.setOptions( command.getOptions() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of CabinLayout {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteCabinLayoutCommand
	 */
	public void delete( DeleteCabinLayoutCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getCabinLayoutId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of CabinLayout {0} ", id );

	}

	/**
	 * Method to retrieve the CabinLayout via CabinLayoutFetchOneSummary
	 * @param 	summary CabinLayoutFetchOneSummary
	 * @return 	CabinLayoutFetchOneResponse
	 */
	public CabinLayout getCabinLayout( CabinLayoutFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "CabinLayoutFetchOneSummary arg cannot be null" );

		CabinLayout entity = null;
		UUID id = summary.getCabinLayoutId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a CabinLayout using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all CabinLayouts
	 *
	 * @return 	List<CabinLayout>
	 */
    public List<CabinLayout> getAllCabinLayout() {
		List<CabinLayout> list = projector.findAll( new FindAllCabinLayoutQuery() );
		return list;
	}

	/**
	 * assign Variant on CabinLayout
	 * @param		command AssignVariantToCabinLayoutCommand
	 */
	public void assignVariant( AssignVariantToCabinLayoutCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignVariant(command.getCabinLayoutId(), command.getAssignment());

	}

